class OrderService:
    """SQLite-backed order service."""

    def __init__(self, db_path, *, clock, id_factory):
        self._db_path = db_path
        self._clock = clock
        self._id_factory = id_factory
        self._conn = sqlite3.connect(db_path, isolation_level=None)
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._conn.execute("PRAGMA foreign_keys=ON")
        self._init_schema()

    def _init_schema(self) -> None:
        try:
            cur = self._conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='schema_info'")
            row = cur.fetchone()
            if row is None:
                self._create_schema()
            else:
                cur = self._conn.execute("SELECT version FROM schema_info WHERE id = 1")
                vrow = cur.fetchone()
                if vrow is None:
                    raise OrderError("SCHEMA_MISMATCH", "schema_info table exists but missing version row", {})
                version = vrow[0]
                if version != _SCHEMA_VERSION:
                    raise OrderError("SCHEMA_MISMATCH", f"unsupported schema version: {version}", {"version": version})
                # Verify all expected tables exist
                expected = {"schema_info", "stock", "orders", "order_items", "idempotency_keys"}
                cur = self._conn.execute("SELECT name FROM sqlite_master WHERE type='table'")
                actual = {r[0] for r in cur.fetchall()}
                if not expected.issubset(actual):
                    raise OrderError("SCHEMA_MISMATCH", "missing expected tables", {"missing": list(expected - actual)})
        except OrderError:
            raise
        except sqlite3.Error as e:
            raise OrderError("STORAGE_ERROR", f"storage error during schema init: {e}", {"detail": str(e)})

    def _create_schema(self) -> None:
        try:
            self._conn.execute("BEGIN IMMEDIATE")
            self._conn.executescript(
                """
                CREATE TABLE IF NOT EXISTS schema_info (
                    id INTEGER PRIMARY KEY CHECK (id = 1),
                    version INTEGER NOT NULL
                );
                CREATE TABLE IF NOT EXISTS stock (
                    sku TEXT PRIMARY KEY,
                    available INTEGER NOT NULL CHECK (available >= 0)
                );
                CREATE TABLE IF NOT EXISTS orders (
                    order_id TEXT PRIMARY KEY,
                    idempotency_key TEXT NOT NULL UNIQUE,
                    status TEXT NOT NULL CHECK (status IN ('pending','paid','shipped','cancelled')),
                    total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
                    payment_id TEXT,
                    created_at REAL NOT NULL,
                    updated_at REAL NOT NULL
                );
                CREATE TABLE IF NOT EXISTS order_items (
                    order_id TEXT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,
                    sku TEXT NOT NULL,
                    quantity INTEGER NOT NULL CHECK (quantity > 0),
                    unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
                    PRIMARY KEY (order_id, sku)
                );
                CREATE TABLE IF NOT EXISTS idempotency_keys (
                    idempotency_key TEXT PRIMARY KEY,
                    order_id TEXT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE
                );
                """
            )
            self._conn.execute("INSERT OR IGNORE INTO schema_info (id, version) VALUES (1, ?)", (_SCHEMA_VERSION,))
            self._conn.execute("COMMIT")
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error during schema creation: {e}", {"detail": str(e)})

    def _now(self) -> float:
        val = self._clock()
        _check_clock_finite(val)
        return float(val)

    def _gen_order_id(self, conn) -> str:
        for attempt in range(3):
            oid = self._id_factory()
            if not _is_nonempty_string(oid):
                raise OrderError("INVALID_DEPENDENCY", "id_factory must return a non-empty string", {"type": type(oid).__name__})
            if oid.strip() == "":
                raise OrderError("INVALID_DEPENDENCY", "id_factory must not return whitespace-only string", {})
            cur = conn.execute("SELECT 1 FROM orders WHERE order_id = ?", (oid,))
            if cur.fetchone() is None:
                return oid
        raise OrderError("ID_COLLISION", "failed to generate unique order id after 3 attempts", {})

    def set_stock(self, sku: str, quantity: int) -> dict:
        _validate_sku(sku)
        if not _is_strict_int(quantity):
            raise OrderError("INVALID_INPUT", "quantity must be a non-negative integer", {"got": type(quantity).__name__})
        if quantity < 0:
            raise OrderError("INVALID_INPUT", "quantity must be >= 0", {"quantity": quantity})

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            self._conn.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                (sku, quantity),
            )
            cur = self._conn.execute("SELECT available FROM stock WHERE sku = ?", (sku,))
            avail = cur.fetchone()[0]
            self._conn.execute("COMMIT")
            return {"sku": sku, "available": avail}
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error in set_stock: {e}", {"detail": str(e)})

    def _validate_items(self, items: object) -> list[dict]:
        if not isinstance(items, list):
            raise OrderError("INVALID_INPUT", "items must be a list", {"got": type(items).__name__})
        if len(items) == 0:
            raise OrderError("INVALID_INPUT", "items must not be empty", {})

        seen_skus = set()
        validated = []
        allowed_keys = {"sku", "quantity", "unit_price_cents"}
        for item in items:
            if not isinstance(item, dict):
                raise OrderError("INVALID_INPUT", "each item must be a dict", {"got": type(item).__name__})
            keys = set(item.keys())
            if keys != allowed_keys:
                extra = keys - allowed_keys
                missing = allowed_keys - keys
                raise OrderError("INVALID_INPUT", "item has wrong fields", {"extra": list(extra), "missing": list(missing)})
            sku = item["sku"]
            _validate_sku(sku)
            quantity = item["quantity"]
            if not _is_strict_int(quantity):
                raise OrderError("INVALID_INPUT", "item quantity must be an integer", {"got": type(quantity).__name__})
            if quantity <= 0:
                raise OrderError("INVALID_INPUT", "item quantity must be > 0", {"quantity": quantity})
            unit_price_cents = item["unit_price_cents"]
            if not _is_strict_int(unit_price_cents):
                raise OrderError("INVALID_INPUT", "item unit_price_cents must be an integer", {"got": type(unit_price_cents).__name__})
            if unit_price_cents < 0:
                raise OrderError("INVALID_INPUT", "item unit_price_cents must be >= 0", {"unit_price_cents": unit_price_cents})
            if sku in seen_skus:
                raise OrderError("INVALID_INPUT", "duplicate sku in items", {"sku": sku})
            seen_skus.add(sku)
            validated.append({"sku": sku, "quantity": quantity, "unit_price_cents": unit_price_cents})

        validated.sort(key=lambda x: x["sku"])
        return validated

    def _canonical_items_key(self, items: list[dict]) -> str:
        """Canonical representation for idempotency comparison."""
        import json
        return json.dumps(items, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)

    def _load_order(self, conn, order_id: str) -> dict | None:
        cur = conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
            "FROM orders WHERE order_id = ?",
            (order_id,),
        )
        row = cur.fetchone()
        if row is None:
            return None
        cur = conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
            (order_id,),
        )
        items = [{"sku": r[0], "quantity": r[1], "unit_price_cents": r[2]} for r in cur.fetchall()]
        return {
            "order_id": row[0],
            "idempotency_key": row[1],
            "status": row[2],
            "items": items,
            "total_cents": row[3],
            "payment_id": row[4],
            "created_at": row[5],
            "updated_at": row[6],
        }

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        _validate_idempotency_key(idempotency_key)
        validated_items = self._validate_items(items)

        try:
            self._conn.execute("BEGIN IMMEDIATE")

            # Check idempotency
            cur = self._conn.execute(
                "SELECT order_id FROM idempotency_keys WHERE idempotency_key = ?",
                (idempotency_key,),
            )
            row = cur.fetchone()
            if row is not None:
                existing_oid = row[0]
                existing_order = self._load_order(self._conn, existing_oid)
                if existing_order is None:
                    self._conn.execute("ROLLBACK")
                    raise OrderError("STORAGE_ERROR", "idempotency key references missing order", {})
                # Compare canonical items
                existing_canonical = self._canonical_items_key(existing_order["items"])
                new_canonical = self._canonical_items_key(validated_items)
                self._conn.execute("COMMIT")
                if existing_canonical == new_canonical:
                    return existing_order
                else:
                    raise OrderError("IDEMPOTENCY_CONFLICT", "idempotency key reused with different items", {})

            # Check stock for all items
            total_cents = 0
            for item in validated_items:
                cur = self._conn.execute("SELECT available FROM stock WHERE sku = ?", (item["sku"],))
                stock_row = cur.fetchone()
                if stock_row is None or stock_row[0] < item["quantity"]:
                    self._conn.execute("ROLLBACK")
                    raise OrderError("INSUFFICIENT_STOCK", f"insufficient stock for sku {item['sku']}", {"sku": item["sku"]})
                total_cents += item["quantity"] * item["unit_price_cents"]

            # Generate order ID
            order_id = self._gen_order_id(self._conn)
            now = self._now()

            # Insert order
            self._conn.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at) "
                "VALUES (?, ?, 'pending', ?, NULL, ?, ?)",
                (order_id, idempotency_key, total_cents, now, now),
            )

            # Insert items and decrement stock
            for item in validated_items:
                self._conn.execute(
                    "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents) VALUES (?, ?, ?, ?)",
                    (order_id, item["sku"], item["quantity"], item["unit_price_cents"]),
                )
                self._conn.execute(
                    "UPDATE stock SET available = available - ? WHERE sku = ?",
                    (item["quantity"], item["sku"]),
                )

            # Insert idempotency mapping
            self._conn.execute(
                "INSERT INTO idempotency_keys (idempotency_key, order_id) VALUES (?, ?)",
                (idempotency_key, order_id),
            )

            order = self._load_order(self._conn, order_id)
            self._conn.execute("COMMIT")
            return order
        except OrderError:
            raise
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error in create_order: {e}", {"detail": str(e)})

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        _validate_order_id(order_id)
        _validate_payment_id(payment_id)
        if not _is_strict_int(amount_cents):
            raise OrderError("INVALID_INPUT", "amount_cents must be an integer", {"got": type(amount_cents).__name__})
        if amount_cents < 0:
            raise OrderError("INVALID_INPUT", "amount_cents must be >= 0", {"amount_cents": amount_cents})

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            order = self._load_order(self._conn, order_id)
            if order is None:
                self._conn.execute("ROLLBACK")
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})

            # Idempotency: same order, same payment_id, same amount -> return current order
            if order["payment_id"] == payment_id and order["total_cents"] == amount_cents:
                self._conn.execute("COMMIT")
                return order

            # Amount mismatch check (before mutation)
            if order["total_cents"] != amount_cents:
                self._conn.execute("ROLLBACK")
                raise OrderError("AMOUNT_MISMATCH", "payment amount does not match order total", {
                    "expected": order["total_cents"],
                    "got": amount_cents,
                })

            # Check if order is already paid with a different payment_id
            if order["status"] == "paid" and order["payment_id"] != payment_id:
                self._conn.execute("ROLLBACK")
                raise OrderError("PAYMENT_CONFLICT", "order already paid with a different payment id", {
                    "existing_payment_id": order["payment_id"],
                })

            # Check if payment_id is used by a different order or different amount
            cur = self._conn.execute(
                "SELECT order_id, total_cents FROM orders WHERE payment_id = ?",
                (payment_id,),
            )
            prow = cur.fetchone()
            if prow is not None:
                if prow[0] != order_id or prow[1] != amount_cents:
                    self._conn.execute("ROLLBACK")
                    raise OrderError("PAYMENT_CONFLICT", "payment id already used for a different order or amount", {
                        "existing_order_id": prow[0],
                    })

            if order["status"] != "pending":
                self._conn.execute("ROLLBACK")
                raise OrderError("INVALID_STATE", f"cannot pay order in status {order['status']}", {"status": order["status"]})

            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status = 'paid', payment_id = ?, updated_at = ? WHERE order_id = ?",
                (payment_id, now, order_id),
            )
            order = self._load_order(self._conn, order_id)
            self._conn.execute("COMMIT")
            return order
        except OrderError:
            raise
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error in pay_order: {e}", {"detail": str(e)})

    def cancel_order(self, order_id: str) -> dict:
        _validate_order_id(order_id)

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            order = self._load_order(self._conn, order_id)
            if order is None:
                self._conn.execute("ROLLBACK")
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})

            if order["status"] == "cancelled":
                self._conn.execute("COMMIT")
                return order

            if order["status"] == "shipped":
                self._conn.execute("ROLLBACK")
                raise OrderError("INVALID_STATE", "cannot cancel a shipped order", {"status": "shipped"})

            if order["status"] not in ("pending", "paid"):
                self._conn.execute("ROLLBACK")
                raise OrderError("INVALID_STATE", f"cannot cancel order in status {order['status']}", {"status": order["status"]})

            # Release stock (exactly once - only if not already released)
            for item in order["items"]:
                self._conn.execute(
                    "UPDATE stock SET available = available + ? WHERE sku = ?",
                    (item["quantity"], item["sku"]),
                )

            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            order = self._load_order(self._conn, order_id)
            self._conn.execute("COMMIT")
            return order
        except OrderError:
            raise
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error in cancel_order: {e}", {"detail": str(e)})

    def ship_order(self, order_id: str) -> dict:
        _validate_order_id(order_id)

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            order = self._load_order(self._conn, order_id)
            if order is None:
                self._conn.execute("ROLLBACK")
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})

            if order["status"] == "shipped":
                self._conn.execute("COMMIT")
                return order

            if order["status"] != "paid":
                self._conn.execute("ROLLBACK")
                raise OrderError("INVALID_STATE", f"cannot ship order in status {order['status']}", {"status": order["status"]})

            now = self._now()
            self._conn.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?",
                (now, order_id),
            )
            order = self._load_order(self._conn, order_id)
            self._conn.execute("COMMIT")
            return order
        except OrderError:
            raise
        except sqlite3.Error as e:
            try:
                self._conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise OrderError("STORAGE_ERROR", f"storage error in ship_order: {e}", {"detail": str(e)})

    def get_order(self, order_id: str) -> dict:
        _validate_order_id(order_id)

        try:
            cur = self._conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
                "FROM orders WHERE order_id = ?",
                (order_id,),
            )
            row = cur.fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
            cur = self._conn.execute(
                "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
                (order_id,),
            )
            items = [{"sku": r[0], "quantity": r[1], "unit_price_cents": r[2]} for r in cur.fetchall()]
            return {
                "order_id": row[0],
                "idempotency_key": row[1],
                "status": row[2],
                "items": items,
                "total_cents": row[3],
                "payment_id": row[4],
                "created_at": row[5],
                "updated_at": row[6],
            }
        except OrderError:
            raise
        except sqlite3.Error as e:
            raise OrderError("STORAGE_ERROR", f"storage error in get_order: {e}", {"detail": str(e)})

    def close(self) -> None:
        try:
            self._conn.close()
        except sqlite3.Error:
            pass


__all__ = ["OrderError", "OrderService"]

