"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid

from src.order_fulfillment import OrderError, OrderService


def _emit_success(result: object) -> None:
    payload = json.dumps({"ok": True, "result": result}, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()


def _emit_error(code: str, message: str, details: dict, exit_code: int) -> None:
    payload = json.dumps(
        {"ok": False, "error": {"code": code, "message": message, "details": details}},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()
    sys.exit(exit_code)


def _read_input(command: str) -> dict:
    """Read one JSON object from stdin. For init/recover/list, empty input is treated as {}."""
    no_input_commands = {}  # order CLI has no commands that accept empty input
    line = sys.stdin.readline()
    if not line or line.strip() == "":
        if command in no_input_commands:
            return {}
        raise OrderError("INVALID_INPUT", "expected non-empty JSON input", {})
    try:
        data = json.loads(line)
    except json.JSONDecodeError as e:
        raise OrderError("INVALID_INPUT", f"invalid JSON: {e}", {})
    if not isinstance(data, dict):
        raise OrderError("INVALID_INPUT", "input must be a JSON object", {"got": type(data).__name__})
    return data


def _validate_fields(data: dict, required: set, allowed: set) -> None:
    keys = set(data.keys())
    missing = required - keys
    extra = keys - allowed
    if missing:
        raise OrderError("INVALID_INPUT", "missing required fields", {"missing": sorted(missing)})
    if extra:
        raise OrderError("INVALID_INPUT", "unknown fields", {"extra": sorted(extra)})


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True, help="Path to SQLite database")
    parser.add_argument("command", help="Command to execute")
    args = parser.parse_args()

    command = args.command
    valid_commands = {"stock", "create", "pay", "cancel", "ship", "get"}
    if command not in valid_commands:
        _emit_error("INVALID_INPUT", f"unknown command: {command}", {"command": command, "valid": sorted(valid_commands)}, 2)

    service = None
    try:
        service = OrderService(
            args.db,
            clock=time.time,
            id_factory=lambda: uuid.uuid4().hex,
        )
    except OrderError as e:
        _emit_error(e.code, e.message, e.details, 2 if e.code == "INVALID_INPUT" else 3)
    except Exception as e:
        _emit_error("STORAGE_ERROR", f"failed to initialize service: {e}", {"detail": str(e)}, 3)

    try:
        data = _read_input(command)

        if command == "stock":
            _validate_fields(data, {"sku", "quantity"}, {"sku", "quantity"})
            result = service.set_stock(data["sku"], data["quantity"])
        elif command == "create":
            _validate_fields(data, {"idempotency_key", "items"}, {"idempotency_key", "items"})
            result = service.create_order(data["idempotency_key"], data["items"])
        elif command == "pay":
            _validate_fields(data, {"order_id", "payment_id", "amount_cents"}, {"order_id", "payment_id", "amount_cents"})
            result = service.pay_order(data["order_id"], data["payment_id"], data["amount_cents"])
        elif command == "cancel":
            _validate_fields(data, {"order_id"}, {"order_id"})
            result = service.cancel_order(data["order_id"])
        elif command == "ship":
            _validate_fields(data, {"order_id"}, {"order_id"})
            result = service.ship_order(data["order_id"])
        elif command == "get":
            _validate_fields(data, {"order_id"}, {"order_id"})
            result = service.get_order(data["order_id"])
        else:
            raise OrderError("INVALID_INPUT", f"unknown command: {command}", {"command": command})

        _emit_success(result)
    except OrderError as e:
        # Domain/contract errors exit 2, storage/internal exit 3
        if e.code in ("STORAGE_ERROR",):
            _emit_error(e.code, e.message, e.details, 3)
        else:
            _emit_error(e.code, e.message, e.details, 2)
    except Exception as e:
        _emit_error("STORAGE_ERROR", f"unexpected error: {e}", {"detail": str(e)}, 3)
    finally:
        if service is not None:
            try:
                service.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

