import sys
import tempfile
import time
from typing import Any


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        # Validate on construction
        _validate_limits_fields(
            self.max_messages,
            self.max_payload_bytes,
            self.max_attempts,
            self.lease_seconds,
            self.retry_delay,
        )


def _validate_limits_fields(max_messages, max_payload_bytes, max_attempts, lease_seconds, retry_delay) -> None:
    # max_messages: positive int, not bool
    if isinstance(max_messages, bool):
        raise SpoolError("INVALID_INPUT", "max_messages must not be bool", {})
    if not isinstance(max_messages, int):
        raise SpoolError("INVALID_INPUT", "max_messages must be an integer", {"got": type(max_messages).__name__})
    if max_messages <= 0:
        raise SpoolError("INVALID_INPUT", "max_messages must be positive", {"max_messages": max_messages})

    if isinstance(max_payload_bytes, bool):
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must not be bool", {})
    if not isinstance(max_payload_bytes, int):
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must be an integer", {"got": type(max_payload_bytes).__name__})
    if max_payload_bytes <= 0:
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must be positive", {"max_payload_bytes": max_payload_bytes})

    if isinstance(max_attempts, bool):
        raise SpoolError("INVALID_INPUT", "max_attempts must not be bool", {})
    if not isinstance(max_attempts, int):
        raise SpoolError("INVALID_INPUT", "max_attempts must be an integer", {"got": type(max_attempts).__name__})
    if max_attempts <= 0:
        raise SpoolError("INVALID_INPUT", "max_attempts must be positive", {"max_attempts": max_attempts})

    # lease_seconds: finite number >= 0, lease_seconds > 0
    if isinstance(lease_seconds, bool):
        raise SpoolError("INVALID_INPUT", "lease_seconds must not be bool", {})
    if not isinstance(lease_seconds, (int, float)):
        raise SpoolError("INVALID_INPUT", "lease_seconds must be a number", {"got": type(lease_seconds).__name__})
    if isinstance(lease_seconds, float) and (math.isnan(lease_seconds) or math.isinf(lease_seconds)):
        raise SpoolError("INVALID_INPUT", "lease_seconds must be finite", {"lease_seconds": lease_seconds})
    if lease_seconds <= 0:
        raise SpoolError("INVALID_INPUT", "lease_seconds must be > 0", {"lease_seconds": lease_seconds})

    # retry_delay: finite number >= 0
    if isinstance(retry_delay, bool):
        raise SpoolError("INVALID_INPUT", "retry_delay must not be bool", {})
    if not isinstance(retry_delay, (int, float)):
        raise SpoolError("INVALID_INPUT", "retry_delay must be a number", {"got": type(retry_delay).__name__})
    if isinstance(retry_delay, float) and (math.isnan(retry_delay) or math.isinf(retry_delay)):
        raise SpoolError("INVALID_INPUT", "retry_delay must be finite", {"retry_delay": retry_delay})
    if retry_delay < 0:
        raise SpoolError("INVALID_INPUT", "retry_delay must be >= 0", {"retry_delay": retry_delay})


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


_SCHEMA_VERSION = 1
_VALID_STATUSES = {"pending", "leased", "acked", "dead"}
_VALID_TOP_LEVEL_FIELDS = {"schema_version", "next_sequence", "messages"}
_VALID_MESSAGE_FIELDS = {
    "message_id", "payload", "status", "available_at",
    "sequence", "attempts", "last_error",
    "lease_token", "worker_id", "expires_at",
}
_PUBLIC_MESSAGE_FIELDS = {
    "message_id", "payload", "status", "available_at",
    "sequence", "attempts", "last_error",
}


def _is_nonempty_string(value: object) -> bool:
    if not isinstance(value, str):
        return False
    if len(value) == 0:
        return False
    return True


def _validate_message_id(msg_id: object, field_name: str = "message_id") -> None:
    if not _is_nonempty_string(msg_id):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be a non-empty string", {"got": repr(msg_id)})
    if msg_id.strip() == "":
        raise SpoolError("INVALID_INPUT", f"{field_name} must not be whitespace-only", {})


def _validate_worker_id(worker_id: object) -> None:
    if not _is_nonempty_string(worker_id):
        raise SpoolError("INVALID_INPUT", "worker_id must be a non-empty string", {"got": repr(worker_id)})
    if worker_id.strip() == "":
        raise SpoolError("INVALID_INPUT", "worker_id must not be whitespace-only", {})


def _validate_finite_number(value: object, field_name: str) -> None:
    if isinstance(value, bool):
        raise SpoolError("INVALID_INPUT", f"{field_name} must not be bool", {})
    if not isinstance(value, (int, float)):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be a number", {"got": type(value).__name__})
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be finite", {field_name: value})


def _canonical_json_bytes(value: object) -> bytes:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"),
        ensure_ascii=False, allow_nan=False,
    ).encode("utf-8")


def _validate_payload(payload: object, max_bytes: int) -> bytes:
    """Validate payload and return its canonical bytes."""
    try:
        canon = _canonical_json_bytes(payload)
    except (TypeError, ValueError) as e:
        raise SpoolError("INVALID_INPUT", f"invalid payload: {e}", {"detail": str(e)})
    if len(canon) > max_bytes:
        raise SpoolError("INVALID_INPUT", "payload exceeds max_payload_bytes", {
            "size": len(canon),
            "max": max_bytes,
        })
    return canon


