class _FileLock:
    """Cross-platform file lock using fcntl (POSIX) or msvcrt (Windows)."""

    def __init__(self, lock_path: str, timeout: float):
        self._lock_path = lock_path
        self._timeout = timeout
        self._fd = None

    def acquire(self) -> None:
        try:
            self._fd = os.open(self._lock_path, os.O_CREAT | os.O_RDWR)
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to open lock file: {e}", {"detail": str(e)})

        deadline = time.time() + self._timeout
        while True:
            try:
                self._try_lock()
                return
            except SpoolError:
                # Could not acquire, check timeout
                if time.time() >= deadline:
                    try:
                        os.close(self._fd)
                    except OSError:
                        pass
                    self._fd = None
                    raise SpoolError("LOCK_TIMEOUT", "timed out waiting for lock", {"timeout": self._timeout})
                time.sleep(0.01)

    def _try_lock(self) -> None:
        try:
            import fcntl
            fcntl.flock(self._fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except ImportError:
            # Windows
            try:
                import msvcrt
                msvcrt.locking(self._fd, msvcrt.LK_NBLCK, 1)
            except OSError as e:
                import errno
                if e.errno in (errno.EACCES, errno.EAGAIN, 36):
                    raise SpoolError("LOCK_TIMEOUT", "lock held by another process", {})
                raise SpoolError("INTERNAL_ERROR", f"lock error: {e}", {"detail": str(e)})
        except OSError as e:
            import errno
            if e.errno in (errno.EACCES, errno.EAGAIN):
                raise SpoolError("LOCK_TIMEOUT", "lock held by another process", {})
            raise SpoolError("INTERNAL_ERROR", f"lock error: {e}", {"detail": str(e)})

    def release(self) -> None:
        if self._fd is None:
            return
        try:
            try:
                import fcntl
                fcntl.flock(self._fd, fcntl.LOCK_UN)
            except ImportError:
                import msvcrt
                msvcrt.locking(self._fd, msvcrt.LK_UNLCK, 1)
        except OSError:
            pass
        try:
            os.close(self._fd)
        except OSError:
            pass
        self._fd = None


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not _is_nonempty_string(root):
            raise SpoolError("INVALID_INPUT", "root must be a non-empty string", {"got": repr(root)})

        self._root = root
        self._clock = clock
        self._failpoint = failpoint

        # Validate limits
        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance", {"got": type(limits).__name__})
        self._limits = limits

        # Validate lock_timeout
        _validate_finite_number(lock_timeout, "lock_timeout")
        if isinstance(lock_timeout, bool):
            raise SpoolError("INVALID_INPUT", "lock_timeout must not be bool", {})
        if lock_timeout < 0:
            raise SpoolError("INVALID_INPUT", "lock_timeout must be >= 0", {"lock_timeout": lock_timeout})
        self._lock_timeout = float(lock_timeout)

        # Constructor must not write - do not create root or lock file here

    def _state_path(self) -> str:
        return os.path.join(self._root, "state.json")

    def _lock_path(self) -> str:
        return os.path.join(self._root, "state.lock")

    def _now(self) -> float:
        val = self._clock()
        if isinstance(val, bool):
            raise SpoolError("INVALID_DEPENDENCY", "clock must not return bool", {})
        if not isinstance(val, (int, float)):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return a number", {"type": type(val).__name__})
        if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return a finite number", {"value": val})
        return float(val)

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    def _ensure_root_dir(self) -> None:
        """Create root directory if it doesn't exist."""
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to create root directory: {e}", {"detail": str(e)})

    def _read_state(self) -> dict:
        """Read and validate state.json. Returns state dict or raises."""
        state_path = self._state_path()
        if not os.path.exists(state_path):
            raise SpoolError("NOT_INITIALIZED", "spool not initialized", {})

        try:
            with open(state_path, "rb") as f:
                raw = f.read()
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to read state file: {e}", {"detail": str(e)})

        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as e:
            raise SpoolError("CORRUPT_STATE", f"state file is not valid UTF-8: {e}", {"detail": str(e)})

        # Check for duplicate keys by using object_pairs_hook
        seen_keys = set()
        def _check_duplicates(pairs):
            result = {}
            for k, v in pairs:
                if k in seen_keys:
                    raise SpoolError("CORRUPT_STATE", f"duplicate key in state JSON: {k}", {"key": k})
                seen_keys.add(k)
                result[k] = v
            return result

        try:
            state = json.loads(text, object_pairs_hook=_check_duplicates)
        except SpoolError:
            raise
        except json.JSONDecodeError as e:
            raise SpoolError("CORRUPT_STATE", f"invalid JSON in state file: {e}", {"detail": str(e)})

        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "state file must contain a JSON object", {"type": type(state).__name__})

        # Validate top-level fields
        keys = set(state.keys())
        if not keys.issubset(_VALID_TOP_LEVEL_FIELDS):
            unknown = keys - _VALID_TOP_LEVEL_FIELDS
            raise SpoolError("CORRUPT_STATE", "unknown top-level fields in state", {"unknown": sorted(unknown)})

        # Check schema_version
        if "schema_version" not in state:
            raise SpoolError("CORRUPT_STATE", "missing schema_version in state", {})
        schema_version = state["schema_version"]
        if isinstance(schema_version, bool) or not isinstance(schema_version, int):
            raise SpoolError("SCHEMA_MISMATCH", "schema_version must be an integer", {"got": type(schema_version).__name__})
        if schema_version != _SCHEMA_VERSION:
            raise SpoolError("SCHEMA_MISMATCH", f"unsupported schema version: {schema_version}", {"version": schema_version})

        # Check next_sequence
        if "next_sequence" not in state:
            raise SpoolError("CORRUPT_STATE", "missing next_sequence in state", {})
        next_seq = state["next_sequence"]
        if isinstance(next_seq, bool) or not isinstance(next_seq, int):
            raise SpoolError("CORRUPT_STATE", "next_sequence must be an integer", {"type": type(next_seq).__name__})
        if next_seq < 1:
            raise SpoolError("CORRUPT_STATE", "next_sequence must be >= 1", {"next_sequence": next_seq})

        # Check messages
        if "messages" not in state:
            raise SpoolError("CORRUPT_STATE", "missing messages in state", {})
        messages = state["messages"]
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be an object", {"type": type(messages).__name__})

        # Validate each message
        for msg_id, msg in messages.items():
            self._validate_stored_message(msg_id, msg, next_seq)

        return state

    def _validate_stored_message(self, msg_id: str, msg: object, next_sequence: int) -> None:
        if not isinstance(msg, dict):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} is not an object", {"message_id": msg_id})

        keys = set(msg.keys())
        if not keys.issubset(_VALID_MESSAGE_FIELDS):
            unknown = keys - _VALID_MESSAGE_FIELDS
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} has unknown fields", {
                "message_id": msg_id,
                "unknown": sorted(unknown),
            })

        # Check required public fields
        required = {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
        missing = required - keys
        if missing:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} missing required fields", {
                "message_id": msg_id,
                "missing": sorted(missing),
            })

        # message_id consistency
        if msg["message_id"] != msg_id:
            raise SpoolError("CORRUPT_STATE", f"message id mismatch for key {msg_id}", {
                "key": msg_id,
                "message_id": msg["message_id"],
            })

        # Validate types
        if not isinstance(msg["message_id"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: message_id must be string", {})
        if not isinstance(msg["status"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: status must be string", {})
        if msg["status"] not in _VALID_STATUSES:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: invalid status", {"status": msg["status"]})

        if isinstance(msg["available_at"], bool) or not isinstance(msg["available_at"], (int, float)):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: available_at must be number", {})
        if isinstance(msg["available_at"], float) and (math.isnan(msg["available_at"]) or math.isinf(msg["available_at"])):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: available_at must be finite", {})

        if isinstance(msg["sequence"], bool) or not isinstance(msg["sequence"], int):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: sequence must be integer", {})
        if msg["sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: sequence must be >= 1", {})
        if msg["sequence"] >= next_sequence:
            # sequence should be < next_sequence
            pass  # Actually next_sequence is the NEXT one to assign, so existing messages should have sequence < next_sequence

        if isinstance(msg["attempts"], bool) or not isinstance(msg["attempts"], int):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: attempts must be integer", {})
        if msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: attempts must be >= 0", {})

        if msg["last_error"] is not None and not isinstance(msg["last_error"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: last_error must be null or string", {})

        # For leased status, check private fields
        if msg["status"] == "leased":
            if "lease_token" not in msg or "worker_id" not in msg or "expires_at" not in msg:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id} missing lease fields", {})
            if not isinstance(msg["lease_token"], str) or not msg["lease_token"]:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid lease_token", {})
            if not isinstance(msg["worker_id"], str) or not msg["worker_id"]:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid worker_id", {})
            if isinstance(msg["expires_at"], bool) or not isinstance(msg["expires_at"], (int, float)):
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid expires_at", {})
        else:
            # Non-leased messages should not have private lease fields (or they should be consistent)
            pass

        # Validate payload is JSON-serializable
        try:
            _canonical_json_bytes(msg["payload"])
        except (TypeError, ValueError):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: invalid payload", {})

    def _write_state(self, state: dict, lock: _FileLock) -> None:
        """Atomically write state to state.json."""
        state_path = self._state_path()

        # Canonical JSON
        canonical = json.dumps(
            state, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False,
        )
        data = canonical.encode("utf-8") + b"\n"

        # Create temp file in same directory
        pid = os.getpid()
        unique = secrets.token_hex(8)
        tmp_name = f".state.{pid}.{unique}.tmp"
        tmp_path = os.path.join(self._root, tmp_name)

        try:
            fd = os.open(tmp_path, os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 0o644)
            try:
                os.write(fd, data)
                os.fsync(fd)
            finally:
                os.close(fd)

            self._call_failpoint("before_replace")

            # Atomic replace
            os.replace(tmp_path, state_path)

            self._call_failpoint("after_replace")

            # Fsync directory
            try:
                dir_fd = os.open(self._root, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except (OSError, AttributeError):
                # Windows may not support fsync on directories; ignore
                pass
        finally:
            # Clean up temp file if it still exists
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except OSError:
                pass

    def _public_message(self, msg: dict) -> dict:
        """Return public representation of a message."""
        return {
            "message_id": msg["message_id"],
            "payload": msg["payload"],
            "status": msg["status"],
            "available_at": msg["available_at"],
            "sequence": msg["sequence"],
            "attempts": msg["attempts"],
            "last_error": msg["last_error"],
        }

    def _mutate(self, mutator) -> Any:
        """
        Acquire lock, read state, call mutator(state), write state, release lock.
        mutator returns the value to return from this function.
        Cleanup happens in finally.
        """
        self._ensure_root_dir()
        lock = _FileLock(self._lock_path(), self._lock_timeout)
        lock.acquired = False
        try:
            lock.acquire()
            lock.acquired = True

            self._call_failpoint("after_lock")

            state = self._read_state()
            result = mutator(state)
            # mutator may have modified state in place and indicated whether to write
            if isinstance(result, tuple) and len(result) == 2 and result[0] == "__write__":
                self._write_state(state, lock)
                return result[1]
            else:
                # No write
                return result
        finally:
            if lock.acquired:
                lock.release()

    def initialize(self) -> dict:
        """Initialize the spool state."""
        self._ensure_root_dir()
        lock = _FileLock(self._lock_path(), self._lock_timeout)
        lock.acquired = False
        try:
            lock.acquire()
            lock.acquired = True

            self._call_failpoint("after_lock")

            # Check if already initialized
            state_path = self._state_path()
            if os.path.exists(state_path):
                # Try to read to validate
                try:
                    state = self._read_state()
                    # Already initialized
                    raise SpoolError("ALREADY_INITIALIZED", "spool already initialized", {})
                except SpoolError as e:
                    if e.code in ("CORRUPT_STATE", "SCHEMA_MISMATCH"):
                        raise  # Don't overwrite corrupt state
                    # NOT_INITIALIZED means file doesn't exist but we just checked it does...
                    raise

            # Create initial state
            state = {
                "schema_version": _SCHEMA_VERSION,
                "next_sequence": 1,
                "messages": {},
            }
            self._write_state(state, lock)
            return {"initialized": True}
        finally:
            if lock.acquired:
                lock.release()

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        _validate_message_id(message_id)
        canon_payload_bytes = _validate_payload(payload, self._limits.max_payload_bytes)

        if available_at is not None:
            _validate_finite_number(available_at, "available_at")
            available_at = float(available_at)

        def _mut(state: dict):
            messages = state["messages"]

            # Check idempotency
            if message_id in messages:
                existing = messages[message_id]
                existing_payload_bytes = _canonical_json_bytes(existing["payload"])
                same_payload = existing_payload_bytes == canon_payload_bytes
                same_available = (
                    (available_at is None and existing["available_at"] == existing["available_at"]) or
                    (available_at is not None and float(existing["available_at"]) == float(available_at))
                )
                # Use proper comparison: if available_at is None, we can't check idempotency by it
                # Actually for idempotency: "same ID with exactly the same canonical payload and numerically equal available_at"
                # If available_at was defaulted (caller passed None), we used clock() at enqueue time.
                # For idempotency check, the caller's available_at (None defaulted) should be compared with stored value.
                # But the stored value is the clock reading. If caller passes None, the "requested" available_at is "now".
                # The spec says "numerically equal available_at" - so if caller passes None, what does "requested" available_at mean?
                # Re-reading spec: "available_at defaults to one clock() reading"
                # "Repeating the same ID with exactly the same canonical payload and numerically equal available_at returns the original message"
                # So the comparison is between the *provided* available_at and the stored one.
                # If the caller provides None, it means "now" which is determined inside this function.
                # For idempotency: if the existing message's available_at matches the effective available_at (which is now if None was passed),
                # then it's idempotent. But that would mean we need to compute effective available_at first.

                # Actually let me re-read: "available_at defaults to one clock() reading and otherwise is a finite number"
                # "Repeating the same ID with exactly the same canonical payload and numerically equal available_at"
                # This means the *effective* available_at (after defaulting) must match.

                # We compute effective_available_at below.
                pass

            # Compute effective available_at
            if available_at is None:
                eff_available_at = self._now()
            else:
                eff_available_at = available_at

            # Now check idempotency properly
            if message_id in messages:
                existing = messages[message_id]
                existing_payload_bytes = _canonical_json_bytes(existing["payload"])
                same_payload = existing_payload_bytes == canon_payload_bytes
                same_available = float(existing["available_at"]) == float(eff_available_at)

                if same_payload and same_available:
                    return self._public_message(existing)
                else:
                    raise SpoolError("IDEMPOTENCY_CONFLICT", "message id reused with different content", {"message_id": message_id})

            # Check capacity
            if len(messages) >= self._limits.max_messages:
                raise SpoolError("CAPACITY_EXCEEDED", "maximum message count reached", {
                    "max": self._limits.max_messages,
                })

            # Assign sequence
            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1

            # Deep-copy payload via serialize/deserialize to detach from caller
            import json as _json
            detached_payload = _json.loads(canon_payload_bytes)

            msg = {
                "message_id": message_id,
                "payload": detached_payload,
                "status": "pending",
                "available_at": eff_available_at,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def claim(self, worker_id: str) -> dict | None:
        _validate_worker_id(worker_id)

        def _mut(state: dict):
            now = self._now()
            messages = state["messages"]

            # Find pending messages with available_at <= now
            candidates = []
            for msg in messages.values():
                if msg["status"] == "pending" and msg["available_at"] <= now:
                    candidates.append(msg)

            if not candidates:
                return None

            # Sort by (available_at, sequence, message_id) and pick minimum
            candidates.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            msg = candidates[0]

            # Generate unpredictable lease token
            lease_token = secrets.token_hex(16)

            # Update message
            msg["status"] = "leased"
            msg["attempts"] = msg["attempts"] + 1
            msg["lease_token"] = lease_token
            msg["worker_id"] = worker_id
            msg["expires_at"] = now + self._limits.lease_seconds

            result = self._public_message(msg)
            result["lease_token"] = lease_token
            return ("__write__", result)

        return self._mutate(_mut)

    def ack(self, message_id: str, lease_token: str) -> dict:
        _validate_message_id(message_id)
        if not _is_nonempty_string(lease_token):
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})
        if lease_token.strip() == "":
            raise SpoolError("INVALID_INPUT", "lease_token must not be whitespace-only", {})

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})

            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"message is not leased (status: {msg['status']})", {
                    "message_id": message_id,
                    "status": msg["status"],
                })

            # Constant-time token comparison
            stored_token = msg.get("lease_token", "")
            if not _constant_time_equal(stored_token, lease_token):
                raise SpoolError("UNAUTHORIZED", "invalid lease token", {"message_id": message_id})

            # Ack: change to acked, clear private lease fields
            msg["status"] = "acked"
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        _validate_message_id(message_id)
        if not _is_nonempty_string(lease_token):
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})
        if lease_token.strip() == "":
            raise SpoolError("INVALID_INPUT", "lease_token must not be whitespace-only", {})
        if not _is_nonempty_string(error):
            raise SpoolError("INVALID_INPUT", "error must be a non-empty string", {})
        if error.strip() == "":
            raise SpoolError("INVALID_INPUT", "error must not be whitespace-only", {})

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})

            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"message is not leased (status: {msg['status']})", {
                    "message_id": message_id,
                    "status": msg["status"],
                })

            # Constant-time token comparison
            stored_token = msg.get("lease_token", "")
            if not _constant_time_equal(stored_token, lease_token):
                raise SpoolError("UNAUTHORIZED", "invalid lease token", {"message_id": message_id})

            # Record error
            msg["last_error"] = error

            # Clear private lease fields
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)

            if msg["attempts"] >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                now = self._now()
                msg["available_at"] = now + self._limits.retry_delay

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def recover(self) -> dict:
        def _mut(state: dict):
            now = self._now()
            messages = state["messages"]
            count = 0

            for msg in messages.values():
                if msg["status"] != "leased":
                    continue
                expires_at = msg.get("expires_at", 0)
                if now >= expires_at:
                    # Recover this message
                    count += 1
                    msg.pop("lease_token", None)
                    msg.pop("worker_id", None)
                    msg.pop("expires_at", None)

                    if msg["attempts"] >= self._limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now

            return ("__write__", {"recovered": count})

        return self._mutate(_mut)

    def get(self, message_id: str) -> dict:
        _validate_message_id(message_id)

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            return self._public_message(messages[message_id])

        return self._mutate(_mut)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str):
                raise SpoolError("INVALID_INPUT", "status must be a string", {"got": type(status).__name__})
            if status not in _VALID_STATUSES:
                raise SpoolError("INVALID_INPUT", f"invalid status: {status}", {"status": status, "valid": sorted(_VALID_STATUSES)})

        def _mut(state: dict):
            messages = state["messages"]
            result = []
            for msg in messages.values():
                if status is not None and msg["status"] != status:
                    continue
                result.append(self._public_message(msg))

            # Sort by (available_at, sequence, message_id)
            result.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return result

        return self._mutate(_mut)


__all__ = ["Limits", "Spool", "SpoolError"]

display.content:
"""Delivery spool - filesystem-backed lease queue."""

from __future__ import annotations

import dataclasses
import hmac
import json
import math
import os
import secrets
import sys
import tempfile
import time
from typing import Any


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        # Validate on construction
        _validate_limits_fields(
            self.max_messages,
            self.max_payload_bytes,
            self.max_attempts,
            self.lease_seconds,
            self.retry_delay,
        )


def _validate_limits_fields(max_messages, max_payload_bytes, max_attempts, lease_seconds, retry_delay) -> None:
    # max_messages: positive int, not bool
    if isinstance(max_messages, bool):
        raise SpoolError("INVALID_INPUT", "max_messages must not be bool", {})
    if not isinstance(max_messages, int):
        raise SpoolError("INVALID_INPUT", "max_messages must be an integer", {"got": type(max_messages).__name__})
    if max_messages <= 0:
        raise SpoolError("INVALID_INPUT", "max_messages must be positive", {"max_messages": max_messages})

    if isinstance(max_payload_bytes, bool):
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must not be bool", {})
    if not isinstance(max_payload_bytes, int):
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must be an integer", {"got": type(max_payload_bytes).__name__})
    if max_payload_bytes <= 0:
        raise SpoolError("INVALID_INPUT", "max_payload_bytes must be positive", {"max_payload_bytes": max_payload_bytes})

    if isinstance(max_attempts, bool):
        raise SpoolError("INVALID_INPUT", "max_attempts must not be bool", {})
    if not isinstance(max_attempts, int):
        raise SpoolError("INVALID_INPUT", "max_attempts must be an integer", {"got": type(max_attempts).__name__})
    if max_attempts <= 0:
        raise SpoolError("INVALID_INPUT", "max_attempts must be positive", {"max_attempts": max_attempts})

    # lease_seconds: finite number >= 0, lease_seconds > 0
    if isinstance(lease_seconds, bool):
        raise SpoolError("INVALID_INPUT", "lease_seconds must not be bool", {})
    if not isinstance(lease_seconds, (int, float)):
        raise SpoolError("INVALID_INPUT", "lease_seconds must be a number", {"got": type(lease_seconds).__name__})
    if isinstance(lease_seconds, float) and (math.isnan(lease_seconds) or math.isinf(lease_seconds)):
        raise SpoolError("INVALID_INPUT", "lease_seconds must be finite", {"lease_seconds": lease_seconds})
    if lease_seconds <= 0:
        raise SpoolError("INVALID_INPUT", "lease_seconds must be > 0", {"lease_seconds": lease_seconds})

    # retry_delay: finite number >= 0
    if isinstance(retry_delay, bool):
        raise SpoolError("INVALID_INPUT", "retry_delay must not be bool", {})
    if not isinstance(retry_delay, (int, float)):
        raise SpoolError("INVALID_INPUT", "retry_delay must be a number", {"got": type(retry_delay).__name__})
    if isinstance(retry_delay, float) and (math.isnan(retry_delay) or math.isinf(retry_delay)):
        raise SpoolError("INVALID_INPUT", "retry_delay must be finite", {"retry_delay": retry_delay})
    if retry_delay < 0:
        raise SpoolError("INVALID_INPUT", "retry_delay must be >= 0", {"retry_delay": retry_delay})


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


_SCHEMA_VERSION = 1
_VALID_STATUSES = {"pending", "leased", "acked", "dead"}
_VALID_TOP_LEVEL_FIELDS = {"schema_version", "next_sequence", "messages"}
_VALID_MESSAGE_FIELDS = {
    "message_id", "payload", "status", "available_at",
    "sequence", "attempts", "last_error",
    "lease_token", "worker_id", "expires_at",
}
_PUBLIC_MESSAGE_FIELDS = {
    "message_id", "payload", "status", "available_at",
    "sequence", "attempts", "last_error",
}


def _is_nonempty_string(value: object) -> bool:
    if not isinstance(value, str):
        return False
    if len(value) == 0:
        return False
    return True


def _validate_message_id(msg_id: object, field_name: str = "message_id") -> None:
    if not _is_nonempty_string(msg_id):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be a non-empty string", {"got": repr(msg_id)})
    if msg_id.strip() == "":
        raise SpoolError("INVALID_INPUT", f"{field_name} must not be whitespace-only", {})


def _validate_worker_id(worker_id: object) -> None:
    if not _is_nonempty_string(worker_id):
        raise SpoolError("INVALID_INPUT", "worker_id must be a non-empty string", {"got": repr(worker_id)})
    if worker_id.strip() == "":
        raise SpoolError("INVALID_INPUT", "worker_id must not be whitespace-only", {})


def _validate_finite_number(value: object, field_name: str) -> None:
    if isinstance(value, bool):
        raise SpoolError("INVALID_INPUT", f"{field_name} must not be bool", {})
    if not isinstance(value, (int, float)):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be a number", {"got": type(value).__name__})
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        raise SpoolError("INVALID_INPUT", f"{field_name} must be finite", {field_name: value})


def _canonical_json_bytes(value: object) -> bytes:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"),
        ensure_ascii=False, allow_nan=False,
    ).encode("utf-8")


def _validate_payload(payload: object, max_bytes: int) -> bytes:
    """Validate payload and return its canonical bytes."""
    try:
        canon = _canonical_json_bytes(payload)
    except (TypeError, ValueError) as e:
        raise SpoolError("INVALID_INPUT", f"invalid payload: {e}", {"detail": str(e)})
    if len(canon) > max_bytes:
        raise SpoolError("INVALID_INPUT", "payload exceeds max_payload_bytes", {
            "size": len(canon),
            "max": max_bytes,
        })
    return canon


def _constant_time_equal(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))


class _FileLock:
    """Cross-platform file lock using fcntl (POSIX) or msvcrt (Windows)."""

    def __init__(self, lock_path: str, timeout: float):
        self._lock_path = lock_path
        self._timeout = timeout
        self._fd = None

    def acquire(self) -> None:
        try:
            self._fd = os.open(self._lock_path, os.O_CREAT | os.O_RDWR)
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to open lock file: {e}", {"detail": str(e)})

        deadline = time.time() + self._timeout
        while True:
            try:
                self._try_lock()
                return
            except SpoolError:
                # Could not acquire, check timeout
                if time.time() >= deadline:
                    try:
                        os.close(self._fd)
                    except OSError:
                        pass
                    self._fd = None
                    raise SpoolError("LOCK_TIMEOUT", "timed out waiting for lock", {"timeout": self._timeout})
                time.sleep(0.01)

    def _try_lock(self) -> None:
        try:
            import fcntl
            fcntl.flock(self._fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except ImportError:
            # Windows
            try:
                import msvcrt
                msvcrt.locking(self._fd, msvcrt.LK_NBLCK, 1)
            except OSError as e:
                import errno
                if e.errno in (errno.EACCES, errno.EAGAIN, 36):
                    raise SpoolError("LOCK_TIMEOUT", "lock held by another process", {})
                raise SpoolError("INTERNAL_ERROR", f"lock error: {e}", {"detail": str(e)})
        except OSError as e:
            import errno
            if e.errno in (errno.EACCES, errno.EAGAIN):
                raise SpoolError("LOCK_TIMEOUT", "lock held by another process", {})
            raise SpoolError("INTERNAL_ERROR", f"lock error: {e}", {"detail": str(e)})

    def release(self) -> None:
        if self._fd is None:
            return
        try:
            try:
                import fcntl
                fcntl.flock(self._fd, fcntl.LOCK_UN)
            except ImportError:
                import msvcrt
                msvcrt.locking(self._fd, msvcrt.LK_UNLCK, 1)
        except OSError:
            pass
        try:
            os.close(self._fd)
        except OSError:
            pass
        self._fd = None


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not _is_nonempty_string(root):
            raise SpoolError("INVALID_INPUT", "root must be a non-empty string", {"got": repr(root)})

        self._root = root
        self._clock = clock
        self._failpoint = failpoint

        # Validate limits
        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance", {"got": type(limits).__name__})
        self._limits = limits

        # Validate lock_timeout
        _validate_finite_number(lock_timeout, "lock_timeout")
        if isinstance(lock_timeout, bool):
            raise SpoolError("INVALID_INPUT", "lock_timeout must not be bool", {})
        if lock_timeout < 0:
            raise SpoolError("INVALID_INPUT", "lock_timeout must be >= 0", {"lock_timeout": lock_timeout})
        self._lock_timeout = float(lock_timeout)

        # Constructor must not write - do not create root or lock file here

    def _state_path(self) -> str:
        return os.path.join(self._root, "state.json")

    def _lock_path(self) -> str:
        return os.path.join(self._root, "state.lock")

    def _now(self) -> float:
        val = self._clock()
        if isinstance(val, bool):
            raise SpoolError("INVALID_DEPENDENCY", "clock must not return bool", {})
        if not isinstance(val, (int, float)):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return a number", {"type": type(val).__name__})
        if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return a finite number", {"value": val})
        return float(val)

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    def _ensure_root_dir(self) -> None:
        """Create root directory if it doesn't exist."""
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to create root directory: {e}", {"detail": str(e)})

    def _read_state(self) -> dict:
        """Read and validate state.json. Returns state dict or raises."""
        state_path = self._state_path()
        if not os.path.exists(state_path):
            raise SpoolError("NOT_INITIALIZED", "spool not initialized", {})

        try:
            with open(state_path, "rb") as f:
                raw = f.read()
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", f"failed to read state file: {e}", {"detail": str(e)})

        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as e:
            raise SpoolError("CORRUPT_STATE", f"state file is not valid UTF-8: {e}", {"detail": str(e)})

        # Check for duplicate keys by using object_pairs_hook
        seen_keys = set()
        def _check_duplicates(pairs):
            result = {}
            for k, v in pairs:
                if k in seen_keys:
                    raise SpoolError("CORRUPT_STATE", f"duplicate key in state JSON: {k}", {"key": k})
                seen_keys.add(k)
                result[k] = v
            return result

        try:
            state = json.loads(text, object_pairs_hook=_check_duplicates)
        except SpoolError:
            raise
        except json.JSONDecodeError as e:
            raise SpoolError("CORRUPT_STATE", f"invalid JSON in state file: {e}", {"detail": str(e)})

        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "state file must contain a JSON object", {"type": type(state).__name__})

        # Validate top-level fields
        keys = set(state.keys())
        if not keys.issubset(_VALID_TOP_LEVEL_FIELDS):
            unknown = keys - _VALID_TOP_LEVEL_FIELDS
            raise SpoolError("CORRUPT_STATE", "unknown top-level fields in state", {"unknown": sorted(unknown)})

        # Check schema_version
        if "schema_version" not in state:
            raise SpoolError("CORRUPT_STATE", "missing schema_version in state", {})
        schema_version = state["schema_version"]
        if isinstance(schema_version, bool) or not isinstance(schema_version, int):
            raise SpoolError("SCHEMA_MISMATCH", "schema_version must be an integer", {"got": type(schema_version).__name__})
        if schema_version != _SCHEMA_VERSION:
            raise SpoolError("SCHEMA_MISMATCH", f"unsupported schema version: {schema_version}", {"version": schema_version})

        # Check next_sequence
        if "next_sequence" not in state:
            raise SpoolError("CORRUPT_STATE", "missing next_sequence in state", {})
        next_seq = state["next_sequence"]
        if isinstance(next_seq, bool) or not isinstance(next_seq, int):
            raise SpoolError("CORRUPT_STATE", "next_sequence must be an integer", {"type": type(next_seq).__name__})
        if next_seq < 1:
            raise SpoolError("CORRUPT_STATE", "next_sequence must be >= 1", {"next_sequence": next_seq})

        # Check messages
        if "messages" not in state:
            raise SpoolError("CORRUPT_STATE", "missing messages in state", {})
        messages = state["messages"]
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be an object", {"type": type(messages).__name__})

        # Validate each message
        for msg_id, msg in messages.items():
            self._validate_stored_message(msg_id, msg, next_seq)

        return state

    def _validate_stored_message(self, msg_id: str, msg: object, next_sequence: int) -> None:
        if not isinstance(msg, dict):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} is not an object", {"message_id": msg_id})

        keys = set(msg.keys())
        if not keys.issubset(_VALID_MESSAGE_FIELDS):
            unknown = keys - _VALID_MESSAGE_FIELDS
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} has unknown fields", {
                "message_id": msg_id,
                "unknown": sorted(unknown),
            })

        # Check required public fields
        required = {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
        missing = required - keys
        if missing:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id} missing required fields", {
                "message_id": msg_id,
                "missing": sorted(missing),
            })

        # message_id consistency
        if msg["message_id"] != msg_id:
            raise SpoolError("CORRUPT_STATE", f"message id mismatch for key {msg_id}", {
                "key": msg_id,
                "message_id": msg["message_id"],
            })

        # Validate types
        if not isinstance(msg["message_id"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: message_id must be string", {})
        if not isinstance(msg["status"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: status must be string", {})
        if msg["status"] not in _VALID_STATUSES:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: invalid status", {"status": msg["status"]})

        if isinstance(msg["available_at"], bool) or not isinstance(msg["available_at"], (int, float)):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: available_at must be number", {})
        if isinstance(msg["available_at"], float) and (math.isnan(msg["available_at"]) or math.isinf(msg["available_at"])):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: available_at must be finite", {})

        if isinstance(msg["sequence"], bool) or not isinstance(msg["sequence"], int):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: sequence must be integer", {})
        if msg["sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: sequence must be >= 1", {})
        if msg["sequence"] >= next_sequence:
            # sequence should be < next_sequence
            pass  # Actually next_sequence is the NEXT one to assign, so existing messages should have sequence < next_sequence

        if isinstance(msg["attempts"], bool) or not isinstance(msg["attempts"], int):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: attempts must be integer", {})
        if msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: attempts must be >= 0", {})

        if msg["last_error"] is not None and not isinstance(msg["last_error"], str):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: last_error must be null or string", {})

        # For leased status, check private fields
        if msg["status"] == "leased":
            if "lease_token" not in msg or "worker_id" not in msg or "expires_at" not in msg:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id} missing lease fields", {})
            if not isinstance(msg["lease_token"], str) or not msg["lease_token"]:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid lease_token", {})
            if not isinstance(msg["worker_id"], str) or not msg["worker_id"]:
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid worker_id", {})
            if isinstance(msg["expires_at"], bool) or not isinstance(msg["expires_at"], (int, float)):
                raise SpoolError("CORRUPT_STATE", f"leased message {msg_id}: invalid expires_at", {})
        else:
            # Non-leased messages should not have private lease fields (or they should be consistent)
            pass

        # Validate payload is JSON-serializable
        try:
            _canonical_json_bytes(msg["payload"])
        except (TypeError, ValueError):
            raise SpoolError("CORRUPT_STATE", f"message {msg_id}: invalid payload", {})

    def _write_state(self, state: dict, lock: _FileLock) -> None:
        """Atomically write state to state.json."""
        state_path = self._state_path()

        # Canonical JSON
        canonical = json.dumps(
            state, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False,
        )
        data = canonical.encode("utf-8") + b"\n"

        # Create temp file in same directory
        pid = os.getpid()
        unique = secrets.token_hex(8)
        tmp_name = f".state.{pid}.{unique}.tmp"
        tmp_path = os.path.join(self._root, tmp_name)

        try:
            fd = os.open(tmp_path, os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 0o644)
            try:
                os.write(fd, data)
                os.fsync(fd)
            finally:
                os.close(fd)

            self._call_failpoint("before_replace")

            # Atomic replace
            os.replace(tmp_path, state_path)

            self._call_failpoint("after_replace")

            # Fsync directory
            try:
                dir_fd = os.open(self._root, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except (OSError, AttributeError):
                # Windows may not support fsync on directories; ignore
                pass
        finally:
            # Clean up temp file if it still exists
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except OSError:
                pass

    def _public_message(self, msg: dict) -> dict:
        """Return public representation of a message."""
        return {
            "message_id": msg["message_id"],
            "payload": msg["payload"],
            "status": msg["status"],
            "available_at": msg["available_at"],
            "sequence": msg["sequence"],
            "attempts": msg["attempts"],
            "last_error": msg["last_error"],
        }

    def _mutate(self, mutator) -> Any:
        """
        Acquire lock, read state, call mutator(state), write state, release lock.
        mutator returns the value to return from this function.
        Cleanup happens in finally.
        """
        self._ensure_root_dir()
        lock = _FileLock(self._lock_path(), self._lock_timeout)
        lock.acquired = False
        try:
            lock.acquire()
            lock.acquired = True

            self._call_failpoint("after_lock")

            state = self._read_state()
            result = mutator(state)
            # mutator may have modified state in place and indicated whether to write
            if isinstance(result, tuple) and len(result) == 2 and result[0] == "__write__":
                self._write_state(state, lock)
                return result[1]
            else:
                # No write
                return result
        finally:
            if lock.acquired:
                lock.release()

    def initialize(self) -> dict:
        """Initialize the spool state."""
        self._ensure_root_dir()
        lock = _FileLock(self._lock_path(), self._lock_timeout)
        lock.acquired = False
        try:
            lock.acquire()
            lock.acquired = True

            self._call_failpoint("after_lock")

            # Check if already initialized
            state_path = self._state_path()
            if os.path.exists(state_path):
                # Try to read to validate
                try:
                    state = self._read_state()
                    # Already initialized
                    raise SpoolError("ALREADY_INITIALIZED", "spool already initialized", {})
                except SpoolError as e:
                    if e.code in ("CORRUPT_STATE", "SCHEMA_MISMATCH"):
                        raise  # Don't overwrite corrupt state
                    # NOT_INITIALIZED means file doesn't exist but we just checked it does...
                    raise

            # Create initial state
            state = {
                "schema_version": _SCHEMA_VERSION,
                "next_sequence": 1,
                "messages": {},
            }
            self._write_state(state, lock)
            return {"initialized": True}
        finally:
            if lock.acquired:
                lock.release()

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        _validate_message_id(message_id)
        canon_payload_bytes = _validate_payload(payload, self._limits.max_payload_bytes)

        if available_at is not None:
            _validate_finite_number(available_at, "available_at")
            available_at = float(available_at)

        def _mut(state: dict):
            messages = state["messages"]

            # Check idempotency
            if message_id in messages:
                existing = messages[message_id]
                existing_payload_bytes = _canonical_json_bytes(existing["payload"])
                same_payload = existing_payload_bytes == canon_payload_bytes
                same_available = (
                    (available_at is None and existing["available_at"] == existing["available_at"]) or
                    (available_at is not None and float(existing["available_at"]) == float(available_at))
                )
                # Use proper comparison: if available_at is None, we can't check idempotency by it
                # Actually for idempotency: "same ID with exactly the same canonical payload and numerically equal available_at"
                # If available_at was defaulted (caller passed None), we used clock() at enqueue time.
                # For idempotency check, the caller's available_at (None defaulted) should be compared with stored value.
                # But the stored value is the clock reading. If caller passes None, the "requested" available_at is "now".
                # The spec says "numerically equal available_at" - so if caller passes None, what does "requested" available_at mean?
                # Re-reading spec: "available_at defaults to one clock() reading"
                # "Repeating the same ID with exactly the same canonical payload and numerically equal available_at returns the original message"
                # So the comparison is between the *provided* available_at and the stored one.
                # If the caller provides None, it means "now" which is determined inside this function.
                # For idempotency: if the existing message's available_at matches the effective available_at (which is now if None was passed),
                # then it's idempotent. But that would mean we need to compute effective available_at first.

                # Actually let me re-read: "available_at defaults to one clock() reading and otherwise is a finite number"
                # "Repeating the same ID with exactly the same canonical payload and numerically equal available_at"
                # This means the *effective* available_at (after defaulting) must match.

                # We compute effective_available_at below.
                pass

            # Compute effective available_at
            if available_at is None:
                eff_available_at = self._now()
            else:
                eff_available_at = available_at

            # Now check idempotency properly
            if message_id in messages:
                existing = messages[message_id]
                existing_payload_bytes = _canonical_json_bytes(existing["payload"])
                same_payload = existing_payload_bytes == canon_payload_bytes
                same_available = float(existing["available_at"]) == float(eff_available_at)

                if same_payload and same_available:
                    return self._public_message(existing)
                else:
                    raise SpoolError("IDEMPOTENCY_CONFLICT", "message id reused with different content", {"message_id": message_id})

            # Check capacity
            if len(messages) >= self._limits.max_messages:
                raise SpoolError("CAPACITY_EXCEEDED", "maximum message count reached", {
                    "max": self._limits.max_messages,
                })

            # Assign sequence
            seq = state["next_sequence"]
            state["next_sequence"] = seq + 1

            # Deep-copy payload via serialize/deserialize to detach from caller
            import json as _json
            detached_payload = _json.loads(canon_payload_bytes)

            msg = {
                "message_id": message_id,
                "payload": detached_payload,
                "status": "pending",
                "available_at": eff_available_at,
                "sequence": seq,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def claim(self, worker_id: str) -> dict | None:
        _validate_worker_id(worker_id)

        def _mut(state: dict):
            now = self._now()
            messages = state["messages"]

            # Find pending messages with available_at <= now
            candidates = []
            for msg in messages.values():
                if msg["status"] == "pending" and msg["available_at"] <= now:
                    candidates.append(msg)

            if not candidates:
                return None

            # Sort by (available_at, sequence, message_id) and pick minimum
            candidates.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            msg = candidates[0]

            # Generate unpredictable lease token
            lease_token = secrets.token_hex(16)

            # Update message
            msg["status"] = "leased"
            msg["attempts"] = msg["attempts"] + 1
            msg["lease_token"] = lease_token
            msg["worker_id"] = worker_id
            msg["expires_at"] = now + self._limits.lease_seconds

            result = self._public_message(msg)
            result["lease_token"] = lease_token
            return ("__write__", result)

        return self._mutate(_mut)

    def ack(self, message_id: str, lease_token: str) -> dict:
        _validate_message_id(message_id)
        if not _is_nonempty_string(lease_token):
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})
        if lease_token.strip() == "":
            raise SpoolError("INVALID_INPUT", "lease_token must not be whitespace-only", {})

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})

            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"message is not leased (status: {msg['status']})", {
                    "message_id": message_id,
                    "status": msg["status"],
                })

            # Constant-time token comparison
            stored_token = msg.get("lease_token", "")
            if not _constant_time_equal(stored_token, lease_token):
                raise SpoolError("UNAUTHORIZED", "invalid lease token", {"message_id": message_id})

            # Ack: change to acked, clear private lease fields
            msg["status"] = "acked"
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        _validate_message_id(message_id)
        if not _is_nonempty_string(lease_token):
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})
        if lease_token.strip() == "":
            raise SpoolError("INVALID_INPUT", "lease_token must not be whitespace-only", {})
        if not _is_nonempty_string(error):
            raise SpoolError("INVALID_INPUT", "error must be a non-empty string", {})
        if error.strip() == "":
            raise SpoolError("INVALID_INPUT", "error must not be whitespace-only", {})

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})

            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"message is not leased (status: {msg['status']})", {
                    "message_id": message_id,
                    "status": msg["status"],
                })

            # Constant-time token comparison
            stored_token = msg.get("lease_token", "")
            if not _constant_time_equal(stored_token, lease_token):
                raise SpoolError("UNAUTHORIZED", "invalid lease token", {"message_id": message_id})

            # Record error
            msg["last_error"] = error

            # Clear private lease fields
            msg.pop("lease_token", None)
            msg.pop("worker_id", None)
            msg.pop("expires_at", None)

            if msg["attempts"] >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                now = self._now()
                msg["available_at"] = now + self._limits.retry_delay

            return ("__write__", self._public_message(msg))

        return self._mutate(_mut)

    def recover(self) -> dict:
        def _mut(state: dict):
            now = self._now()
            messages = state["messages"]
            count = 0

            for msg in messages.values():
                if msg["status"] != "leased":
                    continue
                expires_at = msg.get("expires_at", 0)
                if now >= expires_at:
                    # Recover this message
                    count += 1
                    msg.pop("lease_token", None)
                    msg.pop("worker_id", None)
                    msg.pop("expires_at", None)

                    if msg["attempts"] >= self._limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now

            return ("__write__", {"recovered": count})

        return self._mutate(_mut)

    def get(self, message_id: str) -> dict:
        _validate_message_id(message_id)

        def _mut(state: dict):
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", "message not found", {"message_id": message_id})
            return self._public_message(messages[message_id])

        return self._mutate(_mut)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None:
            if not isinstance(status, str):
                raise SpoolError("INVALID_INPUT", "status must be a string", {"got": type(status).__name__})
            if status not in _VALID_STATUSES:
                raise SpoolError("INVALID_INPUT", f"invalid status: {status}", {"status": status, "valid": sorted(_VALID_STATUSES)})

        def _mut(state: dict):
            messages = state["messages"]
            result = []
            for msg in messages.values():
                if status is not None and msg["status"] != status:
                    continue
                result.append(self._public_message(msg))

            # Sort by (available_at, sequence, message_id)
            result.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return result

        return self._mutate(_mut)


__all__ = ["Limits", "Spool", "SpoolError"]

