"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time

from src.delivery_spool import Limits, Spool, SpoolError


def _emit_success(result: object) -> None:
    payload = json.dumps({"ok": True, "result": result}, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()


def _emit_error(code: str, message: str, details: dict, exit_code: int) -> None:
    payload = json.dumps(
        {"ok": False, "error": {"code": code, "message": message, "details": details}},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    sys.stdout.write(payload + "\n")
    sys.stdout.flush()
    sys.exit(exit_code)


def _read_input(command: str) -> dict:
    """Read one JSON object from stdin. For init/recover/list, empty input is treated as {}."""
    no_input_commands = {"init", "recover", "list"}
    line = sys.stdin.readline()
    if not line or line.strip() == "":
        if command in no_input_commands:
            return {}
        raise SpoolError("INVALID_INPUT", "expected non-empty JSON input", {})
    try:
        data = json.loads(line)
    except json.JSONDecodeError as e:
        raise SpoolError("INVALID_INPUT", f"invalid JSON: {e}", {})
    if not isinstance(data, dict):
        raise SpoolError("INVALID_INPUT", "input must be a JSON object", {"got": type(data).__name__})
    return data


def _validate_fields(data: dict, required: set, allowed: set) -> None:
    keys = set(data.keys())
    missing = required - keys
    extra = keys - allowed
    if missing:
        raise SpoolError("INVALID_INPUT", "missing required fields", {"missing": sorted(missing)})
    if extra:
        raise SpoolError("INVALID_INPUT", "unknown fields", {"extra": sorted(extra)})


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True, help="Path to spool root directory")
    parser.add_argument("command", help="Command to execute")
    args = parser.parse_args()

    command = args.command
    valid_commands = {"init", "enqueue", "claim", "ack", "fail", "recover", "show", "list"}
    if command not in valid_commands:
        _emit_error("INVALID_INPUT", f"unknown command: {command}", {"command": command, "valid": sorted(valid_commands)}, 2)

    spool = None
    try:
        spool = Spool(
            args.root,
            clock=time.time,
            limits=Limits(),
            lock_timeout=10.0,
            failpoint=None,
        )
    except SpoolError as e:
        _emit_error(e.code, e.message, e.details, 2 if e.code == "INVALID_INPUT" else 3)
    except Exception as e:
        _emit_error("INTERNAL_ERROR", f"failed to initialize spool: {e}", {"detail": str(e)}, 3)

    try:
        data = _read_input(command)

        if command == "init":
            _validate_fields(data, set(), set())
            result = spool.initialize()
        elif command == "enqueue":
            _validate_fields(data, {"message_id", "payload"}, {"message_id", "payload", "available_at"})
            kwargs = {"message_id": data["message_id"], "payload": data["payload"]}
            if "available_at" in data:
                kwargs["available_at"] = data["available_at"]
            result = spool.enqueue(**kwargs)
        elif command == "claim":
            _validate_fields(data, {"worker_id"}, {"worker_id"})
            result = spool.claim(data["worker_id"])
        elif command == "ack":
            _validate_fields(data, {"message_id", "lease_token"}, {"message_id", "lease_token"})
            result = spool.ack(data["message_id"], data["lease_token"])
        elif command == "fail":
            _validate_fields(data, {"message_id", "lease_token", "error"}, {"message_id", "lease_token", "error"})
            result = spool.fail(data["message_id"], data["lease_token"], data["error"])
        elif command == "recover":
            _validate_fields(data, set(), set())
            result = spool.recover()
        elif command == "show":
            _validate_fields(data, {"message_id"}, {"message_id"})
            result = spool.get(data["message_id"])
        elif command == "list":
            _validate_fields(data, set(), {"status"})
            status = data.get("status")
            result = spool.list_messages(status=status)
        else:
            raise SpoolError("INVALID_INPUT", f"unknown command: {command}", {"command": command})

        _emit_success(result)
    except SpoolError as e:
        # Domain/contract errors exit 2, storage/corruption/lock/internal exit 3
        exit_3_codes = {"CORRUPT_STATE", "SCHEMA_MISMATCH", "LOCK_TIMEOUT", "INTERNAL_ERROR"}
        if e.code in exit_3_codes:
            _emit_error(e.code, e.message, e.details, 3)
        else:
            _emit_error(e.code, e.message, e.details, 2)
    except Exception as e:
        _emit_error("INTERNAL_ERROR", f"unexpected error: {e}", {"detail": str(e)}, 3)


if __name__ == "__main__":
    main()

