def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
    _validate_order_id(order_id)
    _validate_payment_id(payment_id)
    if not _is_strict_int(amount_cents):
        raise OrderError("INVALID_INPUT", "amount_cents must be an integer", {"got": type(amount_cents).__name__})
    if amount_cents < 0:
        raise OrderError("INVALID_INPUT", "amount_cents must be >= 0", {"amount_cents": amount_cents})

    try:
        self._conn.execute("BEGIN IMMEDIATE")
        order = self._load_order(self._conn, order_id)
        if order is None:
            self._conn.execute("ROLLBACK")
            raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})

        # 1. Idempotency: same order, same payment_id, same amount -> return current order (any status)
        if order["payment_id"] == payment_id and order["total_cents"] == amount_cents:
            self._conn.execute("COMMIT")
            return order

        # 2. Amount mismatch check (before mutation)
        if order["total_cents"] != amount_cents:
            self._conn.execute("ROLLBACK")
            raise OrderError("AMOUNT_MISMATCH", "payment amount does not match order total", {
                "expected": order["total_cents"],
                "got": amount_cents,
            })

        # 3. Different payment ID for the same already-paid order -> PAYMENT_CONFLICT
        if order["payment_id"] is not None and order["payment_id"] != payment_id:
            self._conn.execute("ROLLBACK")
            raise OrderError("PAYMENT_CONFLICT", "order already paid with a different payment id", {
                "existing_payment_id": order["payment_id"],
            })

        # 4. Check if payment_id is used by a different order or different amount
        cur = self._conn.execute(
            "SELECT order_id, total_cents FROM orders WHERE payment_id = ?",
            (payment_id,),
        )
        prow = cur.fetchone()
        if prow is not None:
            if prow[0] != order_id or prow[1] != amount_cents:
                self._conn.execute("ROLLBACK")
                raise OrderError("PAYMENT_CONFLICT", "payment id already used for a different order or amount", {
                    "existing_order_id": prow[0],
                })

        # 5. Status must be pending to accept payment
        if order["status"] != "pending":
            self._conn.execute("ROLLBACK")
            raise OrderError("INVALID_STATE", f"cannot pay order in status {order['status']}", {"status": order["status"]})

        now = self._now()
        self._conn.execute(
            "UPDATE orders SET status = 'paid', payment_id = ?, updated_at = ? WHERE order_id = ?",
            (payment_id, now, order_id),
        )
        order = self._load_order(self._conn, order_id)
        self._conn.execute("COMMIT")
        return order
    except OrderError:
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass
        raise
    except sqlite3.Error as e:
        try:
            self._conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass
        raise OrderError("STORAGE_ERROR", f"storage error in pay_order: {e}", {"detail": str(e)})

